from rich.text import Text

def test_append_tokens_none():
    text = Text("hello")
    try:
        text.append_tokens([ (None, None) ])
    except Exception as e:
        print(f"Caught exception: {type(e).__name__}: {e}")

def test_append_tokens_int():
    text = Text("hello")
    try:
        text.append_tokens([ (123, None) ])
    except Exception as e:
        print(f"Caught exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_append_tokens_none()
    test_append_tokens_int()

